@module support  src=tests/support.lua  loc=253  mode=namespace  self=M

# Imports
  @const util = 'util'  @ 5

# Module-level constants
  @const M = {}  @ 3

# Private functions
  @fn repr(v, depth)  @ 32-54
  @fn deepEq(a, b)  @ 56-62
  @fn toBase36(n)  @ 133-138
  @fn newEventMeta()  @ 183-185
      -- Per-event metadata persists via eventMeta at project scope, keyed by the take's
      -- POOLEDEVTS pool guid. These helpers seed and read it the way production does, so
      -- fixtures need not re-derive the guid or the storage shape.

# Public API (M.*)
  @api M.imgui()  @ 15-30
      -- A stand-in for the ImGui table, for specs that load a module requiring it.
      -- Key and modifier constants are explicit, because cmgr's token tables walk
      -- Key_A + i and Key_0 + i; everything else a module reaches for (flags, style
      -- vars, functions) auto-vivifies to a distinct number.
  @api M.eq(actual, expected, msg)  @ 64-68
  @api M.deepEq(actual, expected, msg)  @ 70-74
  @api M.bagEq(actual, expected, msg)  @ 77-95
      -- Multiset equality: same values under deepEq, ignoring keys/order.
  @api M.truthy(v, msg)  @ 97-99
  @api M.falsy(v, msg)  @ 101-103
  @api M.eventsMatch(actual, expected, msg)  @ 107-117
      -- Assert that an event array contains events matching each expected spec,
      -- in order, matching only the fields present on the spec (subset match).
  @api M.encodeSidecar(cc)  @ 140-159
  @api M.decodeSidecar(body)  @ 161-177
  @api M.poolGuidOf(take)  @ 187-191
  @api M.seedMeta(take, uuid, fields)  @ 193-195
  @api M.loadMeta(take)  @ 197-199
  @api M.fakeDs()  @ 203-220
      -- Minimal dataStore fake for gm specs: get/assign/subscribe over a flat store.
      -- _rewind simulates a REAPER undo rewinding a blob (fires dataChanged invalidate=true).
  @api M.fakeTm(opts)  @ 226-251
      -- Faithful trackerManager fake for gm specs: records staged intent
      -- (add/assign/del) and drives the real preflush/applyEdit/postflush path,
      -- stamping uuids at flush the way REAPER does. opts.length sets the take
      -- edge (default open); opts.uuidMap backs byUuid for the reload specs.

# Uses (outbound edges)
  @use call    util.instantiate  @ newEventMeta:184
  @use require util  @ <load>:5

# Calls (intra-file)
  @call M.eq  @ eventsMatch:108
  @call M.poolGuidOf  @ seedMeta:194 loadMeta:198
  @call deepEq  @ deepEq:59,71 bagEq:87 eventsMatch:111
  @call newEventMeta  @ seedMeta:194 loadMeta:198
  @call repr  @ repr:44,51 eq:66 deepEq:72 bagEq:93 truthy:98 falsy:102 eventsMatch:113
  @call toBase36  @ encodeSidecar:158

# Bindings (by name)
  @bind deepEq  @ 120
  @bind repr  @ 119

# Unresolved receivers
